using System.Text;
using System.Text.Json;
using System.Text.Json.Nodes;
using Grdp.SoftwareIntegration.Worker.Execution;
namespace Grdp.SoftwareIntegration.Worker.Tests;
public sealed class EclipseThermalStageTests : IDisposable {
 private readonly string root=Path.Combine(Path.GetTempPath(),"grdp-thermal-stage",Guid.NewGuid().ToString("N"));
 public EclipseThermalStageTests()=>Directory.CreateDirectory(root);
 public void Dispose()=>Directory.Delete(root,true);
 private EclipseDeckPackage Package(string kind="OFFICIAL") {var path=Path.Combine(root,"THERM3.DATA");File.Copy(Path.Combine(AppContext.BaseDirectory,$"Fixtures/THERMAL-INJECTION-{kind}-BASELINE.DATA"),path);return new EclipseDeckPackageResolver().Resolve(path,root);}
 private static EclipseThermalInjectionParameters Parameters(EclipseDeckPackage p,string field="SURFACE_INJECTION_RATE"){var s=EclipseThermalInjectionReader.Read(p)!;var r=Assert.Single(s.Context.Records);return new(1,r.Well,s.Context.SourceFile,s.Context.SourceSha256,field=="SURFACE_INJECTION_RATE"?r.ControlLineNumber:r.LineNumber,field,field=="SURFACE_INJECTION_RATE"?r.RateUnit:r.TemperatureUnit,field=="SURFACE_INJECTION_RATE"?r.SurfaceInjectionRate:r.OriginalTemperature,field=="SURFACE_INJECTION_RATE"?25:400,1825);}
 [Theory][InlineData("OFFICIAL","SURFACE_INJECTION_RATE","RATE")][InlineData("OFFICIAL","INJECTION_TEMPERATURE","TEMPERATURE")][InlineData("TEMPERATURE","SURFACE_INJECTION_RATE","RATE")][InlineData("TEMPERATURE","INJECTION_TEMPERATURE","TEMPERATURE")]
 public async Task StageInputExactlyMatchesIndependentNativeCase(string kind,string field,string golden){var p=Package(kind);var original=File.ReadAllBytes(p.MainFile);var snapshot=EclipseThermalInjectionReader.Read(p);Assert.True(EclipseThermalInjectionEditor.Matches(snapshot,Parameters(p,field)));await EclipseThermalInjectionEditor.ApplyAsync(p,Parameters(p,field),TestContext.Current.CancellationToken);Assert.Equal(File.ReadAllBytes(Path.Combine(AppContext.BaseDirectory,$"Fixtures/THERMAL-STAGE-{kind}-{golden}.DATA")),File.ReadAllBytes(p.MainFile));Assert.Null(EclipseThermalInjectionReader.Read(p));Assert.Equal("THERMAL",EclipseThermalReader.Read(p)!.ModelType);}
 [Theory][InlineData(0)][InlineData(-1)][InlineData(1824)][InlineData(3650)][InlineData(4015)]
 public async Task WrongBoundaryCannotChangeInput(int day){var p=Package();var parameters=Parameters(p) with {StartTimeDays=day};var original=File.ReadAllBytes(p.MainFile);Assert.False(EclipseThermalInjectionEditor.Matches(EclipseThermalInjectionReader.Read(p),parameters));await Assert.ThrowsAsync<EclipseDeckPackageException>(()=>EclipseThermalInjectionEditor.ApplyAsync(p,parameters,TestContext.Current.CancellationToken));Assert.Equal(original,File.ReadAllBytes(p.MainFile));}
 [Fact] public void AllOriginalInternalReportsAreAvailableAndEndIsExcluded(){var p=Package();var schedule=EclipseThermalStageSchedule.Read(File.ReadAllBytes(p.MainFile));Assert.NotNull(schedule);Assert.Equal(10,schedule.Steps.Count);for(int i=1;i<10;i++)Assert.Equal(i,EclipseThermalStageSchedule.SplitIndex(schedule,i*365));Assert.Equal(-1,EclipseThermalStageSchedule.SplitIndex(schedule,3650));}
 [Theory][InlineData("TSTEP\n0 /")][InlineData("TSTEP\n10*365.5 /")][InlineData("DATES\n1 JAN 1995 /\n/")][InlineData("TSTEP\n5*365 /\nTSTEP\n5*365 /")]
 public void ComplexOrNonIntegerClocksAreNotOffered(string replacement){var p=Package();var text=File.ReadAllText(p.MainFile).Replace("\r\n","\n").Replace("TSTEP\n 10*365 /",replacement);Assert.Null(EclipseThermalStageSchedule.Read(Encoding.UTF8.GetBytes(text)));}
 [Fact] public void VersionThreeRequiresExactNumericBoundaryAndSupportedField(){var p=Package();var parameters=Parameters(p);var options=new JsonSerializerOptions(JsonSerializerDefaults.Web);var input=JsonSerializer.SerializeToElement(new{schemaVersion=EclipseThermalInjectionParameters.StageSchema,parameters.BaselineRunId,parameters.Well,parameters.SourceFile,parameters.SourceSha256,parameters.LineNumber,parameters.Field,parameters.Unit,parameters.OriginalValue,parameters.TargetValue,parameters.StartTimeDays},options);Assert.True(EclipseThermalInjectionParameters.TryParse(input,out var parsed));Assert.Equal(parameters,parsed);foreach(var fault in new[]{"missing","string","fraction","zero","old","extra","field"}){var n=JsonNode.Parse(input.GetRawText())!;if(fault=="missing")n.AsObject().Remove("startTimeDays");if(fault=="string")n["startTimeDays"]="1825";if(fault=="fraction")n["startTimeDays"]=1825.5;if(fault=="zero")n["startTimeDays"]=0;if(fault=="old")n["schemaVersion"]=EclipseThermalInjectionParameters.ControlSchema;if(fault=="extra")n["endTimeDays"]=3650;if(fault=="field")n["field"]="BHP_UPPER_LIMIT";Assert.False(EclipseThermalInjectionParameters.TryParse(JsonSerializer.SerializeToElement(n),out _));}}
}
